// Pure helpers for the Layout Selection Rules screen.
//
// Extracted from SelectionRulesPanel so the list panel and the (separately
// routed) rule editor share ONE parser and ONE save-payload builder. The editor
// needs them for deep links: there is no get-by-id endpoint for a selection
// rule, so opening /…/selection-rules/:rule_id directly re-fetches the list and
// normalizes the matching row exactly the way the list does.

import {
  flatConditionsToAppliesWhen,
  isAppliesWhenEmpty,
  slugify,
} from 'src/pages/Settings/Components/CustomValidationRules/rule-builder-model';
import type { ConditionOp } from 'src/pages/Settings/Components/CustomValidationRules/rule-builder-model';
import type { dynamicObj } from 'src/pages/assets';
import type { Condition, DisplayRule, EditingRule, RuleSource } from './selection-rules.types';

/** layout_type slug → readable label ("field_validation" → "Field validation"). */
export function sentenceCase(raw: string): string {
  const s = (raw || '').replace(/_/g, ' ').trim();
  return s ? s.charAt(0).toUpperCase() + s.slice(1).toLowerCase() : '';
}

// Backend operator spellings → the canonical ConditionOp the editor uses. Kept
// separate from OP_SYMBOLS (display-only) so parsing stays lossless.
const OP_ALIASES: Record<string, ConditionOp> = {
  '=': 'eq',
  eq: 'eq',
  equals: 'eq',
  equal: 'eq',
  '≠': 'neq',
  ne: 'neq',
  neq: 'neq',
  not_equals: 'neq',
  '>': 'gt',
  gt: 'gt',
  greater_than: 'gt',
  '≥': 'gte',
  gte: 'gte',
  greater_than_or_equal: 'gte',
  '<': 'lt',
  lt: 'lt',
  less_than: 'lt',
  '≤': 'lte',
  lte: 'lte',
  less_than_or_equal: 'lte',
  in: 'in',
  not_empty: 'not_empty',
  is_not_empty: 'not_empty',
  // Text-match / presence / regex operators. These were missing, so a saved
  // rule using any of them was silently re-parsed as `eq` on reload
  // (e.g. `doc_origin contains DE` reopened as `doc_origin = DE`), corrupting
  // the rule on the next save round-trip.
  contains: 'contains',
  starts_with: 'starts_with',
  ends_with: 'ends_with',
  empty: 'empty',
  is_empty: 'empty',
  matches: 'matches',
  regex: 'matches',
};

function normalizeOp(raw: string): ConditionOp {
  return OP_ALIASES[String(raw || '').toLowerCase()] || 'eq';
}

/** Human-friendly comparison symbols. An unmapped operator falls through as-is
 *  so a backend spelling we don't know still renders readably. */
export const OP_SYMBOLS: Record<string, string> = {
  eq: '=',
  equals: '=',
  equal: '=',
  ne: '≠',
  neq: '≠',
  not_equals: '≠',
  gt: '>',
  greater_than: '>',
  gte: '≥',
  greater_than_or_equal: '≥',
  lt: '<',
  less_than: '<',
  lte: '≤',
  less_than_or_equal: '≤',
  contains: 'contains',
  not_contains: 'not contains',
  in: 'in',
  starts_with: 'starts with',
  ends_with: 'ends with',
};

function buildCondition(
  field: string,
  rawOp: string,
  rawValue: unknown,
  negate: boolean,
): Condition {
  const op = normalizeOp(rawOp);
  let value: string;
  if (Array.isArray(rawValue)) {
    value = rawValue.map((v) => String(v ?? '')).join(', ');
  } else if (rawValue === undefined || rawValue === null) {
    value = '';
  } else {
    value = String(rawValue);
  }
  return { field, op, value, negate };
}

/** Flatten an applies_when subtree into leaf conditions. Nested all/any groups
 *  are walked and their leaves appended — the editor's condition list is flat. */
function collectConditions(nodes: unknown[], out: Condition[]): void {
  for (const raw of Array.isArray(nodes) ? nodes : []) {
    const node = raw as dynamicObj;
    if (!node || typeof node !== 'object') continue;
    if (Array.isArray(node.all)) {
      collectConditions(node.all as unknown[], out);
    } else if (Array.isArray(node.any)) {
      collectConditions(node.any as unknown[], out);
    } else {
      let inner = node;
      let negate = false;
      if (node.not && typeof node.not === 'object') {
        inner = node.not as dynamicObj;
        negate = true;
      }
      out.push(
        buildCondition(
          String(inner.field || inner.left || inner.attribute || ''),
          String(inner.op || inner.operator || inner.comparator || 'eq'),
          inner.value ?? inner.right ?? inner.expected,
          negate,
        ),
      );
    }
  }
}

/** Parse applies_when into { match, conditions }, tolerating every shape the
 *  backend has emitted: an all/any tree, a bare array, a { conditions } wrapper
 *  with a match flag, or a single bare leaf. */
function extractAppliesWhen(aw: unknown): {
  match: 'all' | 'any';
  conditions: Condition[];
} {
  if (!aw) return { match: 'all', conditions: [] };

  const conditions: Condition[] = [];

  if (Array.isArray(aw)) {
    collectConditions(aw, conditions);
    return { match: 'all', conditions };
  }

  if (typeof aw !== 'object') return { match: 'all', conditions: [] };
  const node = aw as dynamicObj;

  if (Array.isArray(node.any) || Array.isArray(node.all)) {
    const match: 'all' | 'any' = Array.isArray(node.any) ? 'any' : 'all';
    collectConditions(node[match] as unknown[], conditions);
    return { match, conditions };
  }

  const list = node.conditions || node.rules || node.criteria;
  if (Array.isArray(list)) {
    const match: 'all' | 'any' =
      String(node.match || node.match_type || 'all').toLowerCase() === 'any' ? 'any' : 'all';
    collectConditions(list, conditions);
    return { match, conditions };
  }

  if (node.field || node.op || node.operator) {
    collectConditions([node], conditions);
  }
  return { match: 'all', conditions };
}

/** Context normalizeRule needs from its caller: the active layout type (used as
 *  a fallback for the rule's own) and the translated "Untitled rule" label. */
interface NormalizeContext {
  layoutType: string;
  untitledLabel: string;
}

export function normalizeRule(raw: unknown, index: number, ctx: NormalizeContext): DisplayRule {
  const r = (raw || {}) as dynamicObj;

  // Conditions live in `applies_when` — a recursive all/any tree of leaf
  // conditions ({ field, op, value }, optionally wrapped in { not }). An empty
  // tree means "applies to every document". Fall back to older flat shapes.
  let { match, conditions } = extractAppliesWhen(r.applies_when);
  if (!conditions.length && !r.applies_when) {
    const rawConditions = r.conditions || r.rules || r.criteria || r.condition_list || [];
    conditions = (Array.isArray(rawConditions) ? rawConditions : []).map((c) =>
      normalizeCondition(c),
    );
    match = String(r.match_type || r.match || 'all').toLowerCase() === 'any' ? 'any' : 'all';
  }

  const layout = (r.layout || r.layout_template || r.target_layout || {}) as dynamicObj;
  // The API doesn't return a layout title yet, so fall back to the rule_key
  // (e.g. "origin-ar") as the target-layout identifier before the em-dash.
  const targetTitle =
    r.target_layout_title || layout.title || r.layout_title || r.rule_key || r.key || '—';
  const targetType = sentenceCase(
    String(r.layout_type || layout.layout_type || ctx.layoutType || ''),
  );
  // Preserve the resolved layout id so an edit round-trips it back as
  // layout_template_id (the editor's target picker rebinds it on change).
  const layoutTemplateId = String(r.layout_template_id ?? layout.id ?? r.layout_id ?? '');

  return {
    id: String(r.id ?? r.rule_key ?? r.key ?? `rule-${index}`),
    priority: (r.priority ?? r.order ?? r.rank ?? index + 1) as number | string,
    name: String(r.name || r.display_name || r.title || r.rule_key || ctx.untitledLabel),
    key: String(r.rule_key || r.key || ''),
    rule_key: String(r.rule_key || r.key || ''),
    description: String(r.description || ''),
    conditions,
    match,
    targetTitle: String(targetTitle),
    targetType,
    layoutTemplateId,
    source: resolveSource(r),
    active: resolveActive(r),
    isDefault: Boolean(r.is_default ?? r.default ?? false),
  };
}

function normalizeCondition(c: unknown): Condition {
  const cond = (c || {}) as dynamicObj;
  const field = cond.field || cond.left || cond.attribute || cond.key || '';
  const rawOp = String(cond.operator || cond.op || cond.comparator || 'eq');
  const value = cond.value ?? cond.right ?? cond.expected ?? '';
  return buildCondition(String(field), rawOp, value, false);
}

function resolveSource(r: dynamicObj): RuleSource {
  const raw = String(r.source || r.origin || '').toLowerCase();
  if (raw === 'customized') return 'customized';
  if (raw === 'system' || r.is_system === true || r.system === true) {
    return 'system';
  }
  if (r.is_customized === true) return 'customized';
  return 'custom';
}

function resolveActive(r: dynamicObj): boolean {
  const v = r.is_active ?? r.active ?? r.enabled ?? true;
  return Boolean(v);
}

/** A blank rule for the editor's create mode. */
export function blankRule(layoutType: string): EditingRule {
  return {
    id: '',
    priority: '',
    name: '',
    key: '',
    rule_key: '',
    description: '',
    conditions: [{ field: '', op: 'eq', value: '', negate: false }],
    match: 'all',
    targetTitle: '',
    targetType: sentenceCase(layoutType),
    layoutTemplateId: '',
    source: 'custom',
    active: true,
    isDefault: false,
    isNew: true,
  };
}

/** The mutable half of the create/update body — identical for both verbs, so
 *  the editor builds it once and the caller adds the create-only keys. */
export function buildRulePayload(rule: EditingRule): dynamicObj {
  const applies_when = flatConditionsToAppliesWhen(rule.match, rule.conditions);
  // Omit applies_when when the user built no conditions — an empty match
  // ({ all: [] }) is not sent; its absence means "applies unconditionally".
  const conditionParam = isAppliesWhenEmpty(applies_when) ? {} : { applies_when };
  return {
    display_name: rule.name,
    description: rule.description,
    ...conditionParam,
    layout_template_id: rule.layoutTemplateId,
    priority: Number(rule.priority) || 0,
    is_active: rule.active,
  };
}

/** The rule_key sent when creating: the edited key, the original, else a slug
 *  of the display name (the backend derives the same slug). */
export function createRuleKey(rule: EditingRule): string {
  return rule.key || rule.rule_key || slugify(rule.name);
}
